/**
 * MCP 2025-11-25 URL-mode elicitation helpers shared by McpHost,
 * CursorAccountMcpBridge, SessionEngine, and Slack/playground renderers.
 */
import { ErrorCode, McpError, UrlElicitationRequiredError, } from "@modelcontextprotocol/sdk/types.js";
import { isRecord } from "./is-record.js";
/** Opt-in header telling the backend MCP bridge that this turn can show URL elicitations. */
export const MCP_URL_ELICITATION_HEADER = "x-cursor-mcp-url-elicitation";
/** Cap retries per tool call so an incomplete sign-in cannot loop forever. */
export const MAX_URL_ELICITATION_RETRIES_PER_CALL = 2;
export class McpUrlElicitationError extends Error {
    constructor(connection, elicitations, cause) {
        const lead = elicitations[0]?.message || `MCP connection "${connection}" requires sign-in.`;
        super(lead);
        this.name = "McpUrlElicitationError";
        this.connection = connection;
        this.elicitations = elicitations;
        if (cause !== undefined) {
            this.cause = cause;
        }
    }
}
export function isMcpUrlElicitationError(error) {
    return error instanceof McpUrlElicitationError;
}
function parseElicitationItem(raw) {
    if (!isRecord(raw)) {
        return undefined;
    }
    if (raw.mode !== undefined && raw.mode !== "url") {
        return undefined;
    }
    const elicitationId = typeof raw.elicitationId === "string" ? raw.elicitationId.trim() : "";
    const url = typeof raw.url === "string" ? raw.url.trim() : "";
    const message = typeof raw.message === "string" ? raw.message.trim() : "";
    if (elicitationId === "" || url === "") {
        return undefined;
    }
    return { elicitationId, url, message };
}
const URL_ELICITATION_REQUIRED_ERROR_CODE = ErrorCode.UrlElicitationRequired;
/**
 * Extract MCP 2025-11-25 URL elicitations from `UrlElicitationRequiredError`
 * or any `McpError` with JSON-RPC code `-32042`.
 */
export function extractUrlElicitations(error) {
    if (error instanceof UrlElicitationRequiredError) {
        const parsed = error.elicitations
            .map(parseElicitationItem)
            .filter((item) => item !== undefined);
        return parsed.length > 0 ? parsed : undefined;
    }
    if (error instanceof McpError &&
        error.code === URL_ELICITATION_REQUIRED_ERROR_CODE &&
        isRecord(error.data) &&
        Array.isArray(error.data.elicitations)) {
        const parsed = error.data.elicitations
            .map(parseElicitationItem)
            .filter((item) => item !== undefined);
        return parsed.length > 0 ? parsed : undefined;
    }
    return undefined;
}
function isLocalhostName(hostname) {
    const lower = hostname.toLowerCase();
    return lower === "localhost" || lower === "127.0.0.1" || lower === "::1" || lower === "[::1]";
}
/**
 * Local dev and tests may serve sign-in endpoints on loopback `http:`. Hosted
 * Cursor deployments and production environments strictly require `https:`.
 */
export function allowLocalHttpElicitation(options) {
    const nodeEnv = options.nodeEnv ?? process.env.NODE_ENV;
    return !options.hosted && nodeEnv !== "production";
}
/**
 * Validate an MCP server-supplied elicitation URL before showing it to a user.
 * Rejects non-https schemes (`javascript:`, `data:`, `file:`, `cursor:`, etc.),
 * embedded credentials, and non-loopback `http:` URLs.
 */
export function parseElicitationUrl(raw, options) {
    let parsed;
    try {
        parsed = new URL(raw);
    }
    catch {
        return undefined;
    }
    if (parsed.username !== "" || parsed.password !== "") {
        return undefined;
    }
    if (parsed.protocol === "https:") {
        return parsed.host === "" ? undefined : { url: parsed.toString(), host: parsed.host };
    }
    if (parsed.protocol === "http:" &&
        allowLocalHttpElicitation(options) &&
        isLocalhostName(parsed.hostname)) {
        return parsed.host === "" ? undefined : { url: parsed.toString(), host: parsed.host };
    }
    return undefined;
}
/** Bound and strip Slack mrkdwn control characters from a server-supplied prompt. */
export function sanitizeElicitationMessage(raw, maxLength = 200) {
    if (raw === undefined) {
        return undefined;
    }
    const cleaned = raw
        .replace(/[\r\n\t]+/g, " ")
        .replace(/[<>]/g, "")
        .replace(/\s+/g, " ")
        .trim();
    if (cleaned === "") {
        return undefined;
    }
    return cleaned.length > maxLength ? `${cleaned.slice(0, maxLength - 1)}…` : cleaned;
}
export function urlElicitationNoUserMessage(connection, toolName) {
    return `Tool "${toolName}" on "${connection}" needs a signed-in user to complete authentication.`;
}
export function urlElicitationInvalidUrlMessage(connection, toolName) {
    return `Tool "${toolName}" on "${connection}" returned an invalid sign-in URL.`;
}
export function urlElicitationNextTurnMessage(args) {
    return `${args.connection} requires the caller to sign in on ${args.host}. They were sent a private sign-in card for ${args.host}. Do not post a link. Tell them to complete sign-in, then click Connected, and stop: their request continues on their next turn.`;
}
